window.addEventListener('mos:bookmark-denied', () => { document.documentElement.classList.add('mos-bookmark-open'); const el = document.querySelector('.bookmark-experience'); if (el) el.style.display = 'flex'; document.cookie = 'mos-plan-select=; Max-Age=0; path=/; expires=Thu, 01 Jan 1970 00:00:00 UTC;'; el?.querySelector('.subscribe-link')?.addEventListener('click', (e) => { e.preventDefault(); document.cookie = 'mos-plan-select=; Max-Age=0; path=/; expires=Thu, 01 Jan 1970 00:00:00 UTC;'; setTimeout(() => { window.location.href = "/subscribe?regSourceMethod=Bookmarks"; }, 500); }, { once: true }); el?.querySelector('.close-btn')?.addEventListener('click', () => { document.documentElement.classList.remove('mos-bookmark-open'); }, { once: true }); });

Nepali security forces are trying to rescue six Indian tourists who have been stranded by heavy snowfall in the Himalayas near Nepal's deepest lake since Saturday afternoon.

The group, four men and two women, is stuck at Danigad in Shey-Phoksundo National Park, in Dolpa district in the remote north-west of Nepal, according to the district administration.

The Shey Phoksundo lake in the rural municipality of the same name is Nepal's deepest lake at an altitude of 3,600metres (11,800ft) and with the estimated depth of 145m (475ft).

